  const section=$("#captchaSection"),widget=$("#captchaWidget");
  if(!authNeedsCaptcha()){section.classList.add("hidden");updateAuthSubmitState();return;}
  section.classList.remove("hidden");
  if(!SECURITY_CONFIG.captchaRequired){setCaptchaStatus("CAPTCHA desativado na configuração local.");updateAuthSubmitState();return;}
  if(!captchaConfigured()){setCaptchaStatus("Configure a Site Key do Cloudflare Turnstile em security-config.js antes de publicar.","error");updateAuthSubmitState();return;}
  if(!window.turnstile){setCaptchaStatus("Carregando verificação de segurança...");clearTimeout(captchaRetryTimer);if(attempt<240)captchaRetryTimer=setTimeout(()=>ensureCaptchaRendered(attempt+1),250);else setCaptchaStatus("Não foi possível carregar o CAPTCHA. Verifique a conexão e bloqueadores de conteúdo.","error");updateAuthSubmitState();return;}
