    captchaWidgetId=window.turnstile.render(widget,{sitekey:SECURITY_CONFIG.turnstileSiteKey,theme:"dark",language:"pt-BR",size:"flexible",callback:onCaptchaVerified,"expired-callback":()=>onCaptchaVerified(""),"error-callback":()=>{onCaptchaVerified("");setCaptchaStatus("Falha ao validar o CAPTCHA. Tente novamente.","error");}});
