function setAuthMode(mode){
  authMode=mode;hideMfaPanel();const login=mode==="login",signup=mode==="signup",recovery=mode==="recovery",reset=mode==="reset";$("#authTabs").classList.toggle("hidden",recovery||reset);$("#loginTab").classList.toggle("active",login);$("#loginTab").setAttribute("aria-selected",String(login));$("#signupTab").classList.toggle("active",signup);$("#signupTab").setAttribute("aria-selected",String(signup));$("#nameField").classList.toggle("hidden",!signup);$("#emailField").classList.toggle("hidden",reset);$("#passwordField").classList.toggle("hidden",recovery);$("#confirmField").classList.toggle("hidden",!(signup||reset));$("#forgotPasswordBtn").classList.toggle("hidden",!login);$("#authBackBtn").classList.toggle("hidden",!(recovery||reset));$("#passwordLabel").textContent=reset?"Nova senha":"Senha";$("#authSubmit").textContent=signup?"Criar meu usuário":recovery?"Enviar link de recuperação":reset?"Salvar nova senha":"Entrar";$("#authPassword").autocomplete=signup||reset?"new-password":"current-password";$("#authHelp").textContent=signup?"Você receberá um e-mail para confirmar a conta antes do primeiro acesso.":recovery?"Enviaremos um link seguro para o e-mail informado. O link tem validade limitada.":reset?"Crie uma nova senha com pelo menos 8 caracteres.":"Use a mesma conta no PC e no celular para sincronizar.";captchaToken="";if(captchaWidgetId!==null&&window.turnstile){try{window.turnstile.reset(captchaWidgetId);}catch{}}setTimeout(()=>ensureCaptchaRendered(),0);if(recovery)$("#authEmail").focus();else if(reset)$("#authPassword").focus();
}
async function logout(){if(getQueue().length&&!await askConfirmation("Sair com dados pendentes","Existem alterações ainda não sincronizadas. Elas continuarão neste dispositivo, mas é mais seguro aguardar a sincronização.","Sair mesmo assim"))return;try{await authRequest("logout",{},{token:session?.access_token});}catch{}storeSession(null);session=null;appStarted=false;showAuthScreen();$("#accountDialog")?.close();clearAuthFields();setAuthMode("login");showToast("Sessão encerrada.");}

async function api(table,{method="GET",query="",body,prefer="return=representation"}={}){if(!session?.access_token)throw new Error("Sessão expirada");const response=await fetch(`${SUPABASE_URL}/rest/v1/${table}${query}`,{method,headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${session.access_token}`,"Content-Type":"application/json",Prefer:prefer},body:body===undefined?undefined:JSON.stringify(body)});const text=await response.text();const data=text?JSON.parse(text):null;if(!response.ok)throw new Error(data?.message||data?.hint||`Erro ${response.status}`);return data;}
function enqueue(op){const queue=getQueue();queue.push({...op,queuedAt:nowIso()});setQueue(queue);}
async function flushQueue(){if(!navigator.onLine||!session)return;let queue=getQueue();if(!queue.length){setSyncStatus("ok","Sincronizado");return;}setSyncStatus("syncing","Sincronizando");const remaining=[];for(const op of queue){if(op.table==="import_mappings"&&sessionAal()!=="aal2"){remaining.push(op);continue;}try{await api(op.table,{method:op.method,query:op.query||"",body:op.body,prefer:op.prefer||"return=minimal"});}catch(error){console.warn("Operação pendente",op,error);remaining.push(op);if(/relation .* does not exist|column .* does not exist|schema cache/i.test(error.message))state.schemaReady=false;}}setQueue(remaining);saveCache();if(remaining.length&&!remaining.every(op=>op.table==="import_mappings"&&sessionAal()!=="aal2"))showToast("Algumas alterações aguardam a migração do banco ou conexão.","error");}
function upsert(table,row){enqueue({table,method:"POST",query:"?on_conflict=id",body:row,prefer:"resolution=merge-duplicates,return=minimal"});flushQueue();}
function patchRow(table,id,changes){enqueue({table,method:"PATCH",query:`?id=eq.${encodeURIComponent(id)}`,body:changes,prefer:"return=minimal"});flushQueue();}
function deleteRow(table,id){enqueue({table,method:"DELETE",query:`?id=eq.${encodeURIComponent(id)}`,prefer:"return=minimal"});flushQueue();}

