function prepareImport(candidates){const accepted=[];pendingImport=candidates.map(c=>{const duplicate=isDuplicate(c,accepted);if(!duplicate)accepted.push(c);return{...c,duplicate,selected:!duplicate,reconciliationStatus:duplicate?"duplicate":"pending"};});for(const b of pendingBatches){b.duplicateCount=pendingImport.filter(i=>i.importBatchId===b.id&&i.duplicate).length;if(b.openingBalance){const analysis=openingBalanceAnalysis(b);Object.assign(b,{openingExplained:analysis.explainedAmount,openingRemaining:analysis.remainingAmount,detailQuality:analysis.detailQuality,openingStatus:analysis.openingStatus,openingAdjustmentId:analysis.existingAdjustment?.id||null});}}renderImportPreview();const hasContent=pendingImport.length||pendingBatches.some(b=>b.openingBalance||b.statementTotal);$("#importResult").classList.toggle("hidden",!hasContent);if(hasContent)$("#importResult").scrollIntoView({behavior:"smooth",block:"start"});}
function renderStatementPreview(){const statements=pendingBatches.filter(b=>b.openingBalance||b.statementTotal),el=$("#statementReconciliation");el.classList.toggle("hidden",!statements.length);el.innerHTML=statements.map(b=>{const quality=Number(b.detailQuality)||0,hasEquation=b.statementStatus!=="not_applicable"&&Number(b.statementTotal)>0,difference=Math.abs(Number(b.statementDifference)||0),equationOk=hasEquation&&difference<=.01,canApply=b.openingRemaining>.01&&!b.openingAdjustmentId&&b.openingStatus!=="overrepresented"&&b.openingConcept==="opening_balance";return`<article class="statement-card"><div class="card-title-row"><div><p class="eyebrow">OPENING_BALANCE NORMALIZADO</p><h4>${escapeHtml(b.accountLabel||b.cardLabel||b.bankName||"Origem importada")}</h4><small>Período do documento ${escapeHtml(formatMonth(b.statementMonth))} • saldo associado a ${escapeHtml(formatMonth(b.previousPeriod))}</small></div><span class="status-pill ${hasEquation?(equationOk?"good":"bad"):"neutral"}">${hasEquation?(equationOk?"Documento conciliado":"Diferença"):"Sem total-âncora"}</span></div><div class="anchor-grid"><span>Saldo de abertura<strong>${formatMoney(b.openingBalance)}</strong></span><span>Novos lançamentos<strong>${formatMoney(b.newPurchases)}</strong></span><span>Créditos/pagamentos<strong>− ${formatMoney(b.creditsPayments)}</strong></span><span>Total informado<strong>${hasEquation?formatMoney(b.statementTotal):"Não informado"}</strong></span></div><div class="equation-row"><span>${formatMoney(b.openingBalance)} + ${formatMoney(b.newPurchases)} − ${formatMoney(b.creditsPayments)}</span><strong>${hasEquation?`= ${formatMoney(b.statementTotal)}`:`= ${formatMoney(b.expectedTotal)} esperado`}</strong><em class="${hasEquation?(equationOk?"good-text":"bad-text"):"warning-text"}">${hasEquation?`diferença ${formatMoney(b.statementDifference)}`:"sem total final para validar a equação"}</em></div><p class="audit-note">Detecção: ${escapeHtml(b.parserId||"generic")} • confiança ${escapeHtml(b.openingConfidence||"—")} • escopo ${escapeHtml(b.accountScope||"—")} • origem ${escapeHtml(b.openingSourceRef||"—")} • evidência “${escapeHtml(b.openingEvidence||"—")}”.</p><div class="detail-quality"><div><span>Qualidade do detalhamento anterior</span><strong>${quality.toFixed(1).replace(".",",")}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,quality)}%"></div></div><small>${formatMoney(b.openingExplained)} já representados • ${formatMoney(b.openingRemaining)} ainda não explicados</small></div><label class="opening-option ${canApply?"":"disabled"}"><input class="opening-balance-choice" type="checkbox" data-batch-id="${b.id}" ${b.applyOpeningBalance?"checked":""} ${canApply?"":"disabled"}><span><strong>Adicionar apenas a diferença ao período anterior</strong><small>${canApply?`${formatMoney(b.openingRemaining)} como ajuste consolidado/opening_balance, sem criar lançamentos detalhados ou categoria.`:b.openingAdjustmentId?"A diferença já foi adicionada anteriormente; nenhum novo ajuste será criado.":b.openingStatus==="overrepresented"?"O histórico já supera o saldo de abertura; revise a conciliação.":"O saldo de abertura já está explicado pelo histórico."}</small></span></label>${!b.applyOpeningBalance&&b.openingRemaining>.01?`<p class="pending-note">Padrão seguro: a diferença permanece pendente e não entra no histórico sem sua decisão.</p>`:""}</article>`;}).join("");}
function renderImportPreview(){const total=pendingImport.length,duplicates=pendingImport.filter(i=>i.duplicate).length,selected=pendingImport.filter(i=>i.selected&&!i.duplicate).length,hasStatement=pendingBatches.some(b=>b.openingBalance||b.statementTotal),willAdjust=pendingBatches.some(b=>b.applyOpeningBalance&&b.openingRemaining>.01);$("#importCount").textContent=`${total} ${total===1?"item":"itens"}`;$("#importStats").innerHTML=`<div class="import-stat"><strong>${total}</strong><span>identificados</span></div><div class="import-stat"><strong>${duplicates}</strong><span>já representados</span></div><div class="import-stat"><strong>${selected}</strong><span>novos detalhados</span></div>`;$("#confirmImportBtn").textContent=willAdjust?`Confirmar ${selected} + ajuste consolidado`:hasStatement&&!selected?"Salvar conciliação":`Importar ${selected} selecionado${selected===1?"":"s"}`;$("#confirmImportBtn").disabled=!selected&&!hasStatement;renderStatementPreview();$("#importPreview").innerHTML=pendingImport.map((i,index)=>`<article class="preview-item ${i.duplicate?"duplicate":""}" data-preview-index="${index}"><input class="preview-check" type="checkbox" ${i.selected?"checked":""} ${i.duplicate?"disabled":""}><div><div class="original-line"><span>ORIGINAL • linha ${i.sourceLine||"—"}</span><code>${escapeHtml(i.originalDescription)} • ${formatMoney(i.originalAmount)}</code></div><div class="preview-top"><input class="preview-description" value="${escapeHtml(i.description)}" maxlength="90"><strong>${i.type==="income"?"+":"−"} ${formatMoney(i.amount)}</strong></div><div class="preview-meta"><input class="preview-date" type="date" value="${i.date}"><select class="preview-category">${CATEGORIES.map(c=>`<option ${c===i.category?"selected":""}>${escapeHtml(c)}</option>`).join("")}</select><select class="preview-type"><option value="expense" ${i.type==="expense"?"selected":""}>Despesa</option><option value="income" ${i.type==="income"?"selected":""}>Receita</option></select><span class="rule-badge">${i.categorySource==="rule"?`Regra v${i.ruleVersion}`:i.categorySource==="system:v1"?"Sistema v1":"Manual"}</span></div>${i.duplicate?`<div class="duplicate-note">Já representado no histórico — não será duplicado</div>`:""}</div></article>`).join("");}
function updatePreviewItem(event){const article=event.target.closest("[data-preview-index]");if(!article)return;const i=pendingImport[Number(article.dataset.previewIndex)];if(!i)return;if(event.target.matches(".preview-check"))i.selected=event.target.checked;if(event.target.matches(".preview-description"))i.description=event.target.value.trim()||"Importado";if(event.target.matches(".preview-date"))i.date=normalizeDate(event.target.value)||i.date;if(event.target.matches(".preview-category")){i.category=event.target.value;i.categorySource="manual";i.ruleId=null;i.ruleVersion=null;}if(event.target.matches(".preview-type"))i.type=event.target.value;renderImportPreview();}
function updateOpeningBalanceChoice(event){const input=event.target.closest(".opening-balance-choice");if(!input)return;const batch=pendingBatches.find(b=>b.id===input.dataset.batchId);if(!batch)return;batch.applyOpeningBalance=input.checked;renderImportPreview();}
function cancelImport(){pendingImport=[];pendingBatches=[];pendingMapperQueue=[];activeMapperContext=null;$("#importResult").classList.add("hidden");$("#importPreview").innerHTML="";$("#statementReconciliation").innerHTML="";$("#statementReconciliation").classList.add("hidden");$("#unknownMapper").classList.add("hidden");}
function confirmImport(){const selected=pendingImport.filter(i=>i.selected&&!i.duplicate).map(i=>sanitizeTransaction({...i,reconciliationStatus:"reconciled",createdAt:nowIso()})),adjustments=[];for(const batch of pendingBatches){if(!batch.openingBalance||!batch.applyOpeningBalance)continue;const analysis=openingBalanceAnalysis(batch,selected);if(analysis.remainingAmount>.01&&!analysis.existingAdjustment){const adjustment=makeOpeningBalanceAdjustment(batch,batch,analysis.remainingAmount);if(!isDuplicate(adjustment,[...selected,...adjustments]))adjustments.push(adjustment);}}const inserted=[...selected,...adjustments];if(!inserted.length&&!pendingBatches.some(b=>b.openingBalance||b.statementTotal))return showToast("Selecione ao menos um lançamento.","error");state.transactions.push(...inserted);inserted.forEach(t=>upsert("transactions",transactionToRow(t)));for(const batch of pendingBatches){const analysis=openingBalanceAnalysis(batch),detailedInBatch=state.transactions.filter(t=>t.importBatchId===batch.id&&t.entryKind!=="opening_balance");batch.importedCount=detailedInBatch.length;batch.openingExplained=analysis.explainedAmount;batch.openingRemaining=analysis.remainingAmount;batch.detailQuality=analysis.detailQuality;batch.openingStatus=analysis.openingStatus;batch.openingAdjustmentId=analysis.existingAdjustment?.id||null;batch.statementStatus=batch.statementTotal>0?(Math.abs(batch.statementDifference||0)<=.01?"reconciled":"divergent"):"not_applicable";batch.status=batch.statementStatus==="divergent"||analysis.openingStatus==="overrepresented"?"divergent":analysis.remainingAmount>.01?"pending_balance":"reconciled";state.importBatches=state.importBatches.filter(b=>b.id!==batch.id).concat(batch);upsert("import_batches",batchToRow(batch));addAudit("import","import_batch",batch.id,{fileHash:batch.fileHash,total:batch.totalFound,imported:batch.importedCount,duplicates:batch.duplicateCount,openingBalance:batch.openingBalance,openingExplained:batch.openingExplained,openingRemaining:batch.openingRemaining,openingStatus:batch.openingStatus,statementDifference:batch.statementDifference,adjustmentId:batch.openingAdjustmentId,openingConcept:batch.openingConcept,parserId:batch.parserId,openingEvidence:batch.openingEvidence,openingSourceRef:batch.openingSourceRef,openingConfidence:batch.openingConfidence,accountKey:batch.accountKey||batch.cardKey});}saveCache();const latest=inserted.map(t=>monthOf(t.date)).sort().at(-1)||pendingBatches[0]?.statementMonth||currentMonth();$("#dashboardMonth").value=latest;$("#listMonth").value=latest;$("#pasteText").value="";const savedPending=pendingBatches.some(b=>b.openingRemaining>.01&&!b.openingAdjustmentId),insertedCount=inserted.length,adjustmentCount=adjustments.length;cancelImport();renderAll();if(insertedCount)navigate("transactions");else{navigate("planning");switchPlanTab("reconciliation");}showToast(`${selected.length} lançamento(s) detalhado(s) inserido(s)${adjustmentCount?` + ${adjustmentCount} ajuste consolidado`:""}${savedPending?"; saldo anterior pendente para conciliação":""}.`);}

function renderImportBatches(){const batches=[...state.importBatches].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).slice(0,4),el=$("#importBatchSnapshot");el.classList.toggle("empty-state",!batches.length);el.innerHTML=batches.length?batches.map(b=>`<div class="simple-row"><div class="row-main"><strong>${escapeHtml(b.fileName)}</strong><small>${formatDateTime(b.createdAt)} • SHA-256 ${escapeHtml(b.fileHash.slice(0,12))}…${b.openingBalance?` • saldo pendente ${formatMoney(b.openingRemaining)}`:""}</small></div><strong class="${b.status==="reconciled"?"good-text":b.status==="divergent"?"bad-text":"warning-text"}">${b.status==="pending_balance"?"Pendente":b.status==="reconciled"?"Conciliado":"Revisar"}</strong></div>`).join(""):"Nenhuma importação registrada.";}
function renderReconciliation(){const batches=[...state.importBatches].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))),statements=batches.filter(b=>b.openingBalance||b.statementTotal),reconciledStatements=statements.filter(b=>b.statementStatus==="reconciled").length,pendingBalance=round2(statements.reduce((s,b)=>s+(Number(b.openingRemaining)||0),0)),openingTotal=statements.reduce((s,b)=>s+(Number(b.openingBalance)||0),0),detailedValue=statements.reduce((s,b)=>s+(Number(b.openingBalance)||0)*(Number(b.detailQuality)||0)/100,0),detailQuality=openingTotal?detailedValue/openingTotal*100:100,duplicates=batches.reduce((s,b)=>s+b.duplicateCount,0);$("#reconciliationMetrics").innerHTML=`<article class="card metric-card"><p>Documentos conciliados</p><strong>${reconciledStatements}/${statements.length}</strong></article><article class="card metric-card"><p>Saldo pendente</p><strong>${formatMoney(pendingBalance)}</strong></article><article class="card metric-card"><p>Qualidade detalhada</p><strong>${detailQuality.toFixed(1).replace(".",",")}%</strong></article><article class="card metric-card"><p>Duplicidades evitadas</p><strong>${duplicates}</strong></article>`;$("#reconciliationList").innerHTML=batches.length?batches.map(b=>{const tx=state.transactions.filter(t=>t.importBatchId===b.id).slice(0,20),statusLabel=b.status==="pending_balance"?"SALDO PENDENTE":b.status.toUpperCase(),statusClass=b.status==="reconciled"?"good":b.status==="divergent"?"bad":"neutral";return`<article class="card batch-card"><div class="card-title-row"><div><p class="eyebrow">${escapeHtml(statusLabel)}</p><h3>${escapeHtml(b.fileName)}</h3><small>SHA-256 ${escapeHtml(b.fileHash)}</small></div><span class="status-pill ${statusClass}">${b.importedCount}/${b.totalFound}</span></div>${b.openingBalance?`<div class="reconciliation-anchor"><div><span>Saldo anterior</span><strong>${formatMoney(b.openingBalance)}</strong></div><div><span>Novos lançamentos</span><strong>${formatMoney(b.newPurchases)}</strong></div><div><span>Créditos/pagamentos</span><strong>− ${formatMoney(b.creditsPayments)}</strong></div><div><span>Total informado</span><strong>${b.statementTotal?formatMoney(b.statementTotal):"Não informado"}</strong></div></div><p class="audit-note">Diferença da equação: <strong class="${Math.abs(b.statementDifference)<=.01?"good-text":"bad-text"}">${formatMoney(b.statementDifference)}</strong> • detalhamento anterior ${Number(b.detailQuality||0).toFixed(1).replace(".",",")}% • saldo não explicado ${formatMoney(b.openingRemaining)} • ${b.openingStatus==="covered_consolidated"?"coberto por ajuste consolidado":b.openingStatus==="detailed"?"explicado por transações detalhadas":b.openingStatus==="overrepresented"?"histórico acima do saldo informado":"pendente para conciliação"}. Detecção ${escapeHtml(b.parserId||"generic")} • ${escapeHtml(b.openingSourceRef||"origem não informada")} • confiança ${escapeHtml(b.openingConfidence||"—")}.</p>`:""}<div class="batch-stats"><span>Importados <strong>${b.importedCount}</strong></span><span>Duplicados <strong>${b.duplicateCount}</strong></span><span>Erros <strong>${b.errorCount||0}</strong></span></div>${tx.map(t=>`<div class="compare-row"><div><small>${t.entryKind==="opening_balance"?"SALDO ANTERIOR":"ORIGINAL"} • linha ${t.sourceLine||"—"}</small><strong>${escapeHtml(t.originalDescription)} • ${formatMoney(t.originalAmount)}</strong></div><span>→</span><div><small>REGISTRO • ${t.entryKind==="opening_balance"?"saldo consolidado / sem categoria":escapeHtml(t.category)}</small><strong>${escapeHtml(t.description)} • ${formatMoney(t.amount)}</strong></div></div>`).join("")||`<p class="muted">Sem registros importados neste lote.</p>`}</article>`;}).join(""):`<div class="card empty-state">Importe um extrato para iniciar a conciliação.</div>`;}

function prefillRule(description,category){$("#ruleId").value="";$("#rulePattern").value=description;$("#ruleCategory").value=category;$("#ruleMatch").value="contains";$("#rulePriority").value=100;$("#ruleActive").checked=true;}
function onRuleSubmit(event){event.preventDefault();const pattern=$("#rulePattern").value.trim();if(!pattern)return showToast("Informe o texto da regra.","error");const groupId=$("#ruleId").value||uuid(),versions=state.rules.filter(r=>r.groupId===groupId),version=Math.max(0,...versions.map(r=>r.version))+1;versions.filter(r=>r.isCurrent).forEach(r=>{r.isCurrent=false;patchRow("category_rules",r.id,{is_current:false});});const rule={id:uuid(),groupId,version,pattern,match:$("#ruleMatch").value,category:$("#ruleCategory").value,priority:Number($("#rulePriority").value)||100,active:$("#ruleActive").checked,isCurrent:true,createdAt:nowIso()};state.rules.push(rule);saveCache();upsert("category_rules",ruleToRow(rule));addAudit("version","category_rule",rule.id,{groupId,version,pattern,category:rule.category});event.target.reset();$("#ruleId").value="";$("#ruleActive").checked=true;$("#rulePriority").value=100;renderRules();showToast(`Regra salva como versão ${version}.`);}
function editRule(groupId){const r=state.rules.filter(x=>x.groupId===groupId&&x.isCurrent).sort((a,b)=>b.version-a.version)[0];if(!r)return;$("#ruleId").value=r.groupId;$("#rulePattern").value=r.pattern;$("#ruleMatch").value=r.match;$("#ruleCategory").value=r.category;$("#rulePriority").value=r.priority;$("#ruleActive").checked=r.active;window.scrollTo({top:0,behavior:"smooth"});}
async function deactivateRule(groupId){const r=state.rules.find(x=>x.groupId===groupId&&x.isCurrent);if(!r||!await askConfirmation("Desativar regra",`Criar uma nova versão inativa para “${r.pattern}”?`,"Desativar"))return;$("#ruleId").value=groupId;$("#rulePattern").value=r.pattern;$("#ruleMatch").value=r.match;$("#ruleCategory").value=r.category;$("#rulePriority").value=r.priority;$("#ruleActive").checked=false;$("#ruleForm").requestSubmit();}
function renderRules(){const current=state.rules.filter(r=>r.isCurrent).sort((a,b)=>a.priority-b.priority),eligible=state.transactions.filter(t=>t.entryKind!=="opening_balance"),automatic=eligible.filter(t=>t.categorySource==="rule").length,rate=eligible.length?automatic/eligible.length*100:0;$("#ruleAutomationRate").textContent=`${rate.toFixed(1).replace(".",",")}% por regras`;$("#ruleList").innerHTML=current.length?current.map(r=>{const versions=state.rules.filter(v=>v.groupId===r.groupId).sort((a,b)=>b.version-a.version);return`<article class="rule-item ${r.active?"":"inactive"}"><div><strong>SE descrição ${r.match==="contains"?"contém":r.match==="starts_with"?"começa com":"é igual a"} “${escapeHtml(r.pattern)}”</strong><span>ENTÃO ${escapeHtml(r.category)} • prioridade ${r.priority}</span><small>Versão atual ${r.version} • ${versions.length} versão(ões) preservada(s) • ${r.active?"ativa":"inativa"}</small></div><div class="item-actions"><button class="mini-action" data-rule-edit="${r.groupId}">Nova versão</button>${r.active?`<button class="mini-action" data-rule-off="${r.groupId}">Desativar</button>`:""}</div></article>`;}).join(""):`<div class="empty-state">Nenhuma regra personalizada. As regras do sistema continuam visíveis como “Sistema v1”.</div>`;}

function activeScenario(){return state.scenarios.find(s=>s.isActive)||{id:null,name:"Base",incomeChange:0,expenseReduction:0,historyMonths:3,projectionMonths:6,category:"Todas",categoryReduction:0,isActive:true};}
function historyAverages(anchor,months){const period=Array.from({length:months},(_,i)=>shiftMonth(anchor,-i-1)),totals=period.map(m=>totalsFor(transactionsForMonth(m))),categories={};for(const c of CATEGORIES)categories[c]=mean(period.map(m=>transactionsForMonth(m).filter(t=>t.type==="expense"&&t.category===c).reduce((s,t)=>s+t.amount,0)));return{period,income:mean(totals.map(t=>t.income)),expense:mean(totals.map(t=>t.expense)),categories};}
function buildCashflow(anchor,scenario=activeScenario()){const avg=historyAverages(anchor,scenario.historyMonths),rows=[];for(let i=0;i<scenario.projectionMonths;i++){const month=shiftMonth(anchor,i),actual=totalsFor(transactionsForMonth(month)),committed=state.bills.filter(b=>!b.paid&&monthOf(b.due)===month).reduce((s,b)=>s+b.amount,0),categoryCut=scenario.category!=="Todas"?(avg.categories[scenario.category]||0)*(scenario.categoryReduction/100):0,baseExpense=Math.max(0,avg.expense*(1-scenario.expenseReduction/100)-categoryCut),projectedExpense=Math.max(0,baseExpense-actual.expense),baseIncome=Math.max(0,avg.income*(1+scenario.incomeChange/100)),projectedIncome=Math.max(0,baseIncome-actual.income),balance=actual.balance+projectedIncome-committed-projectedExpense;rows.push({month,actualIncome:actual.income,actualExpense:actual.expense,committed,projectedIncome,projectedExpense,balance});}return{rows,avg,scenario};}
function onScenarioSubmit(event){event.preventDefault();state.scenarios.forEach(s=>{if(s.isActive){s.isActive=false;patchRow("cashflow_scenarios",s.id,{is_active:false});}});const s={id:uuid(),name:$("#scenarioName").value.trim()||"Cenário",incomeChange:clamp($("#incomeChange").value,-100,500),expenseReduction:clamp($("#expenseReduction").value,0,100),historyMonths:Number($("#historyMonths").value),projectionMonths:Number($("#projectionMonths").value),category:$("#scenarioCategory").value,categoryReduction:clamp($("#categoryReduction").value,0,100),isActive:true,createdAt:nowIso()};state.scenarios.push(s);saveCache();upsert("cashflow_scenarios",scenarioToRow(s));addAudit("create","cashflow_scenario",s.id,{...s});renderCashflow();renderDashboard();showToast("Cenário salvo e projeção recalculada.");}
function fillScenarioForm(){const s=activeScenario();$("#scenarioName").value=s.name;$("#incomeChange").value=s.incomeChange;$("#expenseReduction").value=s.expenseReduction;$("#historyMonths").value=String(s.historyMonths);$("#projectionMonths").value=String(s.projectionMonths);$("#scenarioCategory").value=s.category;$("#categoryReduction").value=s.categoryReduction;}
function renderCashflow(){fillScenarioForm();const anchor=$("#dashboardMonth").value||currentMonth(),{rows,avg,scenario}=buildCashflow(anchor),first=rows[0]||{};$("#scenarioResultTitle").textContent=`Cenário ${scenario.name}`;$("#cashflowSummary").innerHTML=`<div><span>Realizado</span><strong>${formatMoney((first.actualIncome||0)-(first.actualExpense||0))}</strong></div><div><span>Comprometido</span><strong>${formatMoney(first.committed||0)}</strong></div><div><span>Saldo projetado</span><strong>${formatMoney(first.balance||0)}</strong></div>`;$("#cashflowTable").innerHTML=`<table><thead><tr><th>Mês</th><th>Receita real</th><th>Despesa real</th><th>Comprometido</th><th>Projetado adicional</th><th>Saldo projetado</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escapeHtml(formatMonth(r.month))}</td><td>${formatMoney(r.actualIncome)}</td><td>${formatMoney(r.actualExpense)}</td><td>${formatMoney(r.committed)}</td><td>${formatMoney(r.projectedExpense)}</td><td class="${r.balance>=0?"good-text":"bad-text"}">${formatMoney(r.balance)}</td></tr>`).join("")}</tbody></table>`;$("#cashflowPremises").innerHTML=`<h4>Premissas usadas</h4><ul><li>Média de ${scenario.historyMonths} mês(es): receita ${formatMoney(avg.income)} e despesa ${formatMoney(avg.expense)}.</li><li>Variação de receita: ${scenario.incomeChange}%.</li><li>Redução geral de despesas: ${scenario.expenseReduction}%.</li><li>${scenario.category==="Todas"?"Sem redução adicional por categoria.":`Redução de ${scenario.categoryReduction}% em ${escapeHtml(scenario.category)}.`}</li><li>Contas pendentes entram como comprometidas no mês do vencimento.</li><li>O projetado adicional desconta valores já realizados para evitar dupla contagem.</li></ul>`;}
function renderDashboardCashflow(month){const {rows,avg,scenario}=buildCashflow(month),r=rows[0]||{};$("#cashflowSnapshot").innerHTML=`<div><span>Realizado</span><strong>${formatMoney((r.actualIncome||0)-(r.actualExpense||0))}</strong></div><div><span>Comprometido</span><strong>${formatMoney(r.committed||0)}</strong></div><div><span>Projetado</span><strong>${formatMoney(r.balance||0)}</strong></div>`;$("#cashflowAssumption").textContent=`Cenário ${scenario.name}: média dos ${scenario.historyMonths} meses anteriores; receita média ${formatMoney(avg.income)}; despesa média ${formatMoney(avg.expense)}.`;}

function calculateOpportunities(month){const current=transactionsForMonth(month).filter(t=>t.type==="expense"&&t.entryKind!=="opening_balance"),history=Array.from({length:3},(_,i)=>shiftMonth(month,-i-1)),items=[];for(const category of CATEGORIES.filter(c=>!['Investimentos','Salário'].includes(c))){const spent=current.filter(t=>t.category===category).reduce((s,t)=>s+t.amount,0),values=history.map(m=>transactionsForMonth(m).filter(t=>t.type==="expense"&&t.entryKind!=="opening_balance"&&t.category===category).reduce((s,t)=>s+t.amount,0)).filter(v=>v>0),average=mean(values),potential=average>0?Math.max(0,spent-average):0;if(potential>=Math.max(20,spent*.05))items.push({category,spent,average,potential,historyCount:values.length});}return items.sort((a,b)=>b.potential-a.potential);}
function renderOpportunitySnapshot(month){const item=calculateOpportunities(month)[0],el=$("#opportunitySnapshot");el.classList.toggle("empty-state",!item);el.innerHTML=item?`<div class="opportunity-copy"><strong>Se ${escapeHtml(item.category)} voltar à média dos últimos ${item.historyCount} meses, você pode economizar cerca de ${formatMoney(item.potential)} em ${formatMonth(month)}.</strong><span>Gasto atual ${formatMoney(item.spent)} • média ${formatMoney(item.average)}</span></div>`:"Histórico insuficiente ou gastos dentro da média.";}
function renderOpportunities(){const month=$("#opportunityMonth").value||currentMonth(),items=calculateOpportunities(month),total=items.reduce((s,i)=>s+i.potential,0);$("#opportunityTotal").innerHTML=`<span>Potencial estimado</span><strong>${formatMoney(total)}</strong>`;$("#opportunityList").innerHTML=items.length?items.map(i=>`<article class="opportunity-item"><div><strong>${escapeHtml(i.category)}</strong><span>Atual ${formatMoney(i.spent)} • média histórica ${formatMoney(i.average)}</span></div><div><strong>${formatMoney(i.potential)}</strong><button class="mini-action" data-opportunity-category="${escapeHtml(i.category)}">Ver gastos</button></div></article>`).join(""):`<div class="empty-state">Ainda não há aumento material contra a média dos três meses anteriores.</div>`;}

function onBillSubmit(event){event.preventDefault();const description=$("#billDescription").value.trim(),amount=Math.abs(parseMoney($("#billAmount").value)),due=normalizeDate($("#billDue").value);if(!description||!amount||!due)return showToast("Preencha a conta corretamente.","error");const bill={id:uuid(),description,amount,due,paid:false,createdAt:nowIso()};state.bills.push(bill);saveCache();upsert("bills",billToRow(bill));addAudit("create","bill",bill.id,{due,amount});event.target.reset();$("#billDue").value=today();renderBills();renderCashflow();showToast("Conta comprometida adicionada.");}
async function handleBillAction(button){const id=button.dataset.billPay||button.dataset.billDelete,bill=state.bills.find(b=>b.id===id);if(!bill)return;if(button.dataset.billDelete){if(!await askConfirmation("Excluir conta",`Deseja excluir “${bill.description}”?`,"Excluir"))return;state.bills=state.bills.filter(b=>b.id!==id);deleteRow("bills",id);}else{bill.paid=!bill.paid;upsert("bills",billToRow(bill));}saveCache();renderBills();renderCashflow();showToast(button.dataset.billDelete?"Conta excluída.":bill.paid?"Conta marcada como paga.":"Conta reaberta.");}
function renderBills(){const bills=[...state.bills].sort((a,b)=>a.paid-b.paid||a.due.localeCompare(b.due)),pending=bills.filter(b=>!b.paid);$("#billSummary").innerHTML=`<span>${pending.length} pendente${pending.length===1?"":"s"}</span><strong>${formatMoney(pending.reduce((s,b)=>s+b.amount,0))}</strong>`;$("#billList").innerHTML=bills.length?bills.map(b=>`<article class="transaction-item ${b.paid?"income":"expense"}"><span class="transaction-symbol">${b.paid?"✓":"!"}</span><div class="transaction-content"><strong>${escapeHtml(b.description)}</strong><small>Vence ${formatDate(b.due)} • ${b.paid?"Paga":"Comprometida"}</small></div><div class="transaction-side"><strong>${formatMoney(b.amount)}</strong><div class="item-actions"><button class="mini-action" data-bill-pay="${b.id}">${b.paid?"Reabrir":"Marcar paga"}</button><button class="mini-action" data-bill-delete="${b.id}">Excluir</button></div></div></article>`).join(""):`<div class="card empty-state">Nenhuma conta cadastrada.</div>`;}
function saveSettings(event){event.preventDefault();const month=$("#dashboardMonth").value||currentMonth(),amount=Math.abs(parseMoney($("#monthlyBudget").value)),existing=state.budgets.find(b=>b.month===month),budget={id:existing?.id||uuid(),month,amount};state.budgets=state.budgets.filter(b=>b.month!==month).concat(budget);saveCache();upsert("budgets",{id:budget.id,user_id:session.user.id,month:monthDate(month),amount,created_at:nowIso(),updated_at:nowIso()});renderDashboard();showToast(`Orçamento de ${formatMonth(month)} salvo.`);}

async function exportBackup(){if(sessionAal()!=="aal2")return requireAal2(()=>exportBackup(),"Exportar o backup completo");const payload={app:"Copiloto Financeiro",version:APP_VERSION,exportedAt:nowIso(),userId:session.user.id,data:state,queue:getQueue()};const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`copiloto-financeiro-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast("Backup completo exportado.");}
async function restoreBackup(file){if(!file)return;if(sessionAal()!=="aal2")return requireAal2(()=>restoreBackup(file),"Restaurar um backup completo");try{const payload=JSON.parse(await file.text()),data=payload.data||payload;if(!Array.isArray(data.transactions))throw new Error("Formato inválido");if(!await askConfirmation("Restaurar backup",`Serão adicionados ${data.transactions.length} lançamentos e os demais registros do arquivo.`,"Restaurar"))return;for(const raw of data.transactions){const t=sanitizeTransaction({...raw,id:raw.id||uuid()});state.transactions=state.transactions.filter(x=>x.id!==t.id).concat(t);upsert("transactions",transactionToRow(t));}for(const raw of data.bills||[]){const b={...raw,id:raw.id||uuid()};state.bills=state.bills.filter(x=>x.id!==b.id).concat(b);upsert("bills",billToRow(b));}saveCache();renderAll();showToast("Backup restaurado e colocado na fila de sincronização.");}catch(error){showToast(`Backup inválido: ${error.message}`,"error");}finally{$("#restoreFile").value="";}}
async function clearAllData(){if(sessionAal()!=="aal2")return requireAal2(()=>clearAllData(),"Apagar todos os dados");if(!await askConfirmation("Apagar meus dados","Esta ação excluirá seus registros do Supabase e deste dispositivo. A conta de acesso será mantida.","Apagar dados"))return;setLoading(true,"Apagando seus dados...");try{for(const table of TABLES){try{await api(table,{method:"DELETE",query:`?user_id=eq.${session.user.id}`,prefer:"return=minimal"});}catch(error){console.warn(table,error);}}state=defaultState();localStorage.removeItem(userKey(CACHE_PREFIX));localStorage.removeItem(userKey(QUEUE_PREFIX));renderAll();showToast("Dados financeiros apagados.");}finally{setLoading(false);}}

