function registerServiceWorker(){if("serviceWorker"in navigator&&location.protocol.startsWith("http"))navigator.serviceWorker.register("./sw.js").catch(console.warn);if(location.protocol==="file:")$("#pdfHint").textContent="Publique em HTTPS para usar login, PDF, instalação e modo offline.";}
async function enterApp(){if(!session)return;showAppScreen();state=loadCache();if(!appStarted){populateCategories();initializeValues();appStarted=true;}renderAll();setLoading(true,"Carregando sua base financeira...");try{await loadRemote();await migrateLegacy();renderAll();if(!state.schemaReady)showToast("Execute as migrações SQL até a v4.6 no Supabase para ativar o modelo AAL1/AAL2.","error");}finally{setLoading(false);}const initial=location.hash.slice(1);navigate(["dashboard","add","transactions","import","planning"].includes(initial)?initial:"dashboard");updateMfaSecurityCard();}
async function init(){
  bindEvents();registerServiceWorker();setAuthMode("login");
  const callback=readRecoveryCallback();
  if(callback.confirmed){
    storeSession(normalizeSession(callback.session));
    showToast("E-mail confirmado. Você pode ativar MFA depois em Ajustes > Segurança.");
    await routeAuthenticatedSession();
    return;
  }
  if(applyRecoveryCallback(callback))return;
  session=await restoreSession();
  if(session)await routeAuthenticatedSession();else showAuthScreen();
}
